document.addEventListener("DOMContentLoaded", (() => { let e = new Date; document.querySelector('input[type="date"]').value = e.toISOString().split("T")[0]; const t = document.getElementById("Progress"); t && t.addEventListener("submit", (async e => { e.preventDefault(); const t = document.getElementById("InputActivities"), n = document.getElementById("Tanggal"), a = document.getElementById("InputVolume"), o = document.getElementById("Unit"), u = document.getElementById("InputCompletion"), l = { rak: t.value, tgl: n.value, volume: a.value, satuan: o.value, waktu: u.value }; try { const e = await fetch("/api/progress", { method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify(l) }); if (!e.ok) throw new Error(`HTTP error! status: ${e.status}`); Swal.fire({ icon: "success", title: "Succeed", text: "Kegiatan berhasil disimpan", showConfirmButton: !1, timer: 2e3 }), t.value = "", a.value = "", u.value = "" } catch (e) { } })) }));